Literal.Value:
'{
  "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
  "data": {
    "name": "dataset"
  },
  "padding": {
    "left": 0,
    "right": 4,
    "top": 1,
    "bottom": 2
  },
  "transform": [
    {
      "window": [
        {
          "op": "row_number",
          "as": "year_number"
        }
      ],
      "sort": [
        {
          "field": "Year",
          "order": "ascending"
        }
      ]
    },
    {
      "joinaggregate": [
        {
          "op": "max",
          "field": "Spending",
          "as": "spending_max"
        },
        {
          "op": "max",
          "field": "Payments",
          "as": "payments_max"
        },
        {
          "op": "min",
          "field": "Spending",
          "as": "spending_min"
        },
        {
          "op": "min",
          "field": "Payments",
          "as": "payments_min"
        },
        {
          "op": "valid",
          "field": "Spending",
          "as": "years_in_view"
        }
      ]
    },
    {
      "calculate": "max(isValid(datum[''spending_max'']) ? datum[''spending_max''] : 0, isValid(datum[''payments_max'']) ? datum[''payments_max''] : 0, 0)",
      "as": "highest"
    },
    {
      "calculate": "min(isValid(datum[''spending_min'']) ? datum[''spending_min''] : 0, isValid(datum[''payments_min'']) ? datum[''payments_min''] : 0, 0)",
      "as": "lowest"
    },
    {
      "calculate": "datum[''highest''] > 0 ? datum[''highest''] + 0.25 * (datum[''highest''] - datum[''lowest'']) : 0",
      "as": "scale_top"
    },
    {
      "calculate": "datum[''lowest''] < 0 ? datum[''lowest''] - 0.25 * (datum[''highest''] - datum[''lowest'']) : 0",
      "as": "scale_bottom"
    },
    {
      "calculate": "toString(datum[''Year''])",
      "as": "Year text"
    },
    {
      "calculate": "pbiFormat(datum[''Spending''], ''+0.0%;−0.0%;0.0%'')",
      "as": "Spending growth"
    },
    {
      "calculate": "pbiFormat(datum[''Payments''], ''+0.0%;−0.0%;0.0%'')",
      "as": "Payments growth"
    },
    {
      "calculate": "pbiFormat(datum[''Spent now''], ''#,0.00'')",
      "as": "Spent"
    },
    {
      "calculate": "pbiFormat(datum[''Spent before''], ''#,0.00'')",
      "as": "Spent a year before"
    },
    {
      "calculate": "pbiFormat(datum[''Payments now''], datum[''Payments now''] < 100 ? ''#,0.0'' : ''#,0'')",
      "as": "Payments count"
    },
    {
      "calculate": "pbiFormat(datum[''Payments before''], datum[''Payments now''] < 100 ? ''#,0.0'' : ''#,0'')",
      "as": "Payments a year before"
    }
  ],
  "encoding": {
    "x": {
      "field": "Year",
      "type": "ordinal",
      "axis": null,
      "title": null,
      "scale": {
        "paddingInner": 0.2,
        "paddingOuter": 0.1
      }
    }
  },
  "layer": [
    {
      "mark": {
        "type": "rule",
        "opacity": 0
      },
      "encoding": {
        "y": {
          "field": "scale_bottom",
          "type": "quantitative",
          "axis": null,
          "title": null,
          "scale": {
            "zero": true,
            "nice": false,
            "range": [
              {
                "expr": "height"
              },
              46
            ]
          }
        },
        "y2": {
          "field": "scale_top"
        },
        "tooltip": null
      }
    },
    {
      "mark": {
        "type": "rule",
        "color": "#4F5966",
        "strokeWidth": 1
      },
      "encoding": {
        "x": {
          "value": 0
        },
        "x2": {
          "value": "width"
        },
        "y": {
          "datum": 0,
          "type": "quantitative"
        },
        "opacity": {
          "condition": {
            "test": "datum[''year_number''] == 1 && datum[''years_in_view''] > 0",
            "value": 1
          },
          "value": 0
        },
        "tooltip": null
      }
    },
    {
      "mark": {
        "type": "bar",
        "color": "#344054",
        "cornerRadiusEnd": 2,
        "xOffset": {
          "expr": "-1 * (bandwidth(''x'') / 4 + 0.5)"
        },
        "width": {
          "expr": "bandwidth(''x'') / 2 - 1"
        }
      },
      "encoding": {
        "y": {
          "field": "Spending",
          "type": "quantitative"
        },
        "tooltip": [
          {
            "field": "Year text",
            "title": "Year"
          },
          {
            "field": "Spending growth"
          },
          {
            "field": "Spent",
            "title": "Spent (bn SAR)"
          },
          {
            "field": "Spent a year before",
            "title": "Same weeks a year before (bn SAR)"
          },
          {
            "field": "Weeks compared"
          }
        ]
      }
    },
    {
      "mark": {
        "type": "text",
        "baseline": "bottom",
        "fontSize": 12,
        "color": "#4F5966",
        "xOffset": {
          "expr": "-1 * (bandwidth(''x'') / 4 + 0.5)"
        }
      },
      "encoding": {
        "y": {
          "value": {
            "expr": "isValid(datum[''Spending'']) ? scale(''y'', datum[''Spending'']) + (datum[''Spending''] < 0 ? 16 : -4) : height"
          }
        },
        "text": {
          "value": {
            "expr": "isValid(datum[''Spending'']) ? pbiFormat(datum[''Spending''], ''+0.0%;−0.0%;0.0%'') : ''''"
          }
        },
        "tooltip": null
      }
    },
    {
      "mark": {
        "type": "bar",
        "color": "#AEB7C2",
        "cornerRadiusEnd": 2,
        "xOffset": {
          "expr": "1 * (bandwidth(''x'') / 4 + 0.5)"
        },
        "width": {
          "expr": "bandwidth(''x'') / 2 - 1"
        }
      },
      "encoding": {
        "y": {
          "field": "Payments",
          "type": "quantitative"
        },
        "tooltip": [
          {
            "field": "Year text",
            "title": "Year"
          },
          {
            "field": "Payments growth"
          },
          {
            "field": "Payments count",
            "title": "Payments (millions)"
          },
          {
            "field": "Payments a year before",
            "title": "Same weeks a year before (millions)"
          },
          {
            "field": "Weeks compared"
          }
        ]
      }
    },
    {
      "mark": {
        "type": "text",
        "baseline": "bottom",
        "fontSize": 12,
        "color": "#4F5966",
        "xOffset": {
          "expr": "1 * (bandwidth(''x'') / 4 + 0.5)"
        }
      },
      "encoding": {
        "y": {
          "value": {
            "expr": "isValid(datum[''Payments'']) ? scale(''y'', datum[''Payments'']) + (datum[''Payments''] < 0 ? 16 : -4) : height"
          }
        },
        "text": {
          "value": {
            "expr": "isValid(datum[''Payments'']) ? pbiFormat(datum[''Payments''], ''+0.0%;−0.0%;0.0%'') : ''''"
          }
        },
        "tooltip": null
      }
    },
    {
      "mark": {
        "type": "text",
        "baseline": "top",
        "dy": 6,
        "fontSize": 12,
        "color": "#4F5966"
      },
      "encoding": {
        "y": {
          "value": "height"
        },
        "tooltip": null,
        "text": {
          "value": {
            "expr": "datum[''years_in_view''] > 0 ? toString(datum[''Year'']) : ''''"
          }
        }
      }
    },
    {
      "mark": {
        "type": "text",
        "align": "left",
        "baseline": "top",
        "fontSize": 14.67,
        "fontWeight": 600,
        "color": "#13161B"
      },
      "encoding": {
        "x": {
          "value": -1
        },
        "y": {
          "value": 3
        },
        "tooltip": null,
        "text": {
          "value": {
            "expr": "datum[''year_number''] == 1 ? ''Growth year by year'' : ''''"
          }
        }
      }
    },
    {
      "mark": {
        "type": "text",
        "align": "left",
        "baseline": "top",
        "fontSize": 12,
        "color": "#4F5966"
      },
      "encoding": {
        "x": {
          "value": -1
        },
        "y": {
          "value": 25
        },
        "tooltip": null,
        "text": {
          "value": {
            "expr": "datum[''year_number''] == 1 ? datum[''Subtitle''] : ''''"
          }
        }
      }
    },
    {
      "mark": {
        "type": "text",
        "align": "left",
        "baseline": "middle",
        "dx": -132,
        "fontSize": 12,
        "color": "#4F5966"
      },
      "encoding": {
        "x": {
          "value": "width"
        },
        "y": {
          "value": 13
        },
        "text": {
          "value": {
            "expr": "datum[''year_number''] == 1 && datum[''years_in_view''] > 0 ? ''Spending'' : ''''"
          }
        },
        "tooltip": null
      }
    },
    {
      "mark": {
        "type": "text",
        "align": "left",
        "baseline": "middle",
        "dx": -146,
        "fontSize": 12,
        "color": "#344054"
      },
      "encoding": {
        "x": {
          "value": "width"
        },
        "y": {
          "value": 13
        },
        "text": {
          "value": {
            "expr": "datum[''year_number''] == 1 && datum[''years_in_view''] > 0 ? ''■'' : ''''"
          }
        },
        "tooltip": null
      }
    },
    {
      "mark": {
        "type": "text",
        "align": "left",
        "baseline": "middle",
        "dx": -52,
        "fontSize": 12,
        "color": "#4F5966"
      },
      "encoding": {
        "x": {
          "value": "width"
        },
        "y": {
          "value": 13
        },
        "text": {
          "value": {
            "expr": "datum[''year_number''] == 1 && datum[''years_in_view''] > 0 ? ''Payments'' : ''''"
          }
        },
        "tooltip": null
      }
    },
    {
      "mark": {
        "type": "text",
        "align": "left",
        "baseline": "middle",
        "dx": -66,
        "fontSize": 12,
        "color": "#AEB7C2"
      },
      "encoding": {
        "x": {
          "value": "width"
        },
        "y": {
          "value": 13
        },
        "text": {
          "value": {
            "expr": "datum[''year_number''] == 1 && datum[''years_in_view''] > 0 ? ''■'' : ''''"
          }
        },
        "tooltip": null
      }
    }
  ]
}'
